public sealed class App:Application {
 [STAThread] public static int Main(string[] args){bool smoke=args.Contains("--startup-smoke-test");try{if(smoke){DocumentStore.Verify();FileResultContext.Verify();OutlineReader.Verify();}var app=new App();var window=new LibraryWindow();if(smoke)window.VerifyViewerControls();bool rendered=false;if(smoke)window.ContentRendered+=(_,_)=>{rendered=true;app.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>app.Shutdown(0)));};int code=app.Run(window);return smoke&&!rendered?1:code;}catch(Exception e){if(smoke){try{File.WriteAllText("startup-smoke-error.txt",e.ToString());}catch{}}else MessageBox.Show("تعذر بدء المكتبة:\n"+e.Message,"الأنصاري");return 1;}}
}
public sealed class SearchHit {
 public required string Path{get;init;}public required int Index{get;init;}public required string Text{get;init;}public required string[] Words{get;init;}public required long Length{get;init;}public required long Ticks{get;init;}public int Offset{get;init;}
}
public sealed class DisplayRow {
 public string Text{get;init;}="";public string[] Words{get;init;}=Array.Empty<string>();public Brush Fill{get;init;}=Brushes.White;public Thickness Indent{get;init;}=new(5);public bool Jump{get;init;}public SearchHit? Hit{get;init;}public FileResultContext? Context{get;init;}public Dictionary<string,FileResultContext>? Contexts{get;init;}public int Depth{get;init;}public bool Open{get;set;}=true;public List<DisplayRow> Children{get;}=new();
}
public sealed class HighlightBlock:TextBlock {
 public static readonly DependencyProperty RowProperty=DependencyProperty.Register("Row",typeof(DisplayRow),typeof(HighlightBlock),new PropertyMetadata(null,(d,e)=>((HighlightBlock)d).Paint()));
 public DisplayRow? Row{get=>(DisplayRow?)GetValue(RowProperty);set=>SetValue(RowProperty,value);}
 static readonly Brush[] Colors={Brushes.Yellow,Brushes.LightGreen,Brushes.LightPink,Brushes.LightSkyBlue};Run? anchor;
 public HighlightBlock(){TextWrapping=TextWrapping.Wrap;Padding=new Thickness(6);}
 void Paint(){Inlines.Clear();anchor=null;var row=Row;if(row==null)return;Background=row.Fill;Margin=row.Indent;string text=row.Text;int at=0;while(at<text.Length){int next=-1,which=-1;for(int i=0;i<row.Words.Length;i++){if(row.Words[i].Length==0)continue;int p=text.IndexOf(row.Words[i],at,StringComparison.OrdinalIgnoreCase);if(p>=0&&(next<0||p<next)){next=p;which=i;}}if(next<0){Inlines.Add(new Run(text[at..]));break;}if(next>at)Inlines.Add(new Run(text[at..next]));var run=new Run(text.Substring(next,row.Words[which].Length)){Background=Colors[which%Colors.Length],Foreground=Brushes.Black};Inlines.Add(run);anchor??=run;at=next+row.Words[which].Length;}}
 public void JumpNow(){if(Row?.Jump==true&&IsLoaded)anchor?.BringIntoView();}
}
public sealed class FastList:ListBox {
 public FastList(){ScrollViewer.SetCanContentScroll(this,true);ScrollViewer.SetHorizontalScrollBarVisibility(this,ScrollBarVisibility.Disabled);VirtualizingPanel.SetIsVirtualizing(this,true);VirtualizingPanel.SetVirtualizationMode(this,VirtualizationMode.Recycling);VirtualizingPanel.SetScrollUnit(this,ScrollUnit.Pixel);VirtualizingPanel.SetCacheLength(this,new VirtualizationCacheLength(1));VirtualizingPanel.SetCacheLengthUnit(this,VirtualizationCacheLengthUnit.Page);var panel=new FrameworkElementFactory(typeof(VirtualizingStackPanel));ItemsPanel=new ItemsPanelTemplate(panel);var text=new FrameworkElementFactory(typeof(HighlightBlock));text.SetBinding(HighlightBlock.RowProperty,new Binding());ItemTemplate=new DataTemplate{VisualTree=text};var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty,HorizontalAlignment.Stretch));ItemContainerStyle=style;}
}
