 public LibraryWindow(){Title="الأنصاري — بلا فهرسة — عارض ومخطط تفصيلي — مراجعة 3";Width=1300;Height=850;MinWidth=850;MinHeight=550;FlowDirection=FlowDirection.RightToLeft;var root=new DockPanel{Margin=new Thickness(10)};Content=root;DockPanel.SetDock(tools,Dock.Top);root.Children.Add(tools);DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);
  Add("إضافة مجلد",Folder);Add("إضافة ملفات",()=>{var d=new OpenFileDialog{Filter="Word DOCX|*.docx",Multiselect=true};if(d.ShowDialog(this)==true)Merge(d.FileNames);return Task.CompletedTask;});tools.Children.Add(query);Add("بحث عام",()=>Search(false));Add("إلغاء",()=>{cancel?.Cancel();return Task.CompletedTask;},false);fold=Add("طي نتائج المكتبة",()=>{Fold();return Task.CompletedTask;},false);Add("طي / فرد ملفات المكتبة",()=>{bool open=!library.Items.OfType<TreeViewItem>().All(n=>n.IsExpanded);foreach(var n in library.Items.OfType<TreeViewItem>())n.IsExpanded=open;return Task.CompletedTask;},false);Add("نسخ النتيجة",()=>{if(results.SelectedItem is DisplayRow{Hit:not null} r)Clipboard.SetText(r.Hit.Path+"\n"+r.Hit.Text);return Task.CompletedTask;},false);Add("تقرير",()=>{MessageBox.Show(string.Join("\n",errors.TakeLast(100)),"تقرير");return Task.CompletedTask;},false);
  var grid=new Grid();root.Children.Add(grid);foreach(double w in new[]{2d,0,3,0,5})grid.ColumnDefinitions.Add(new ColumnDefinition{Width=w==0?new GridLength(5):new GridLength(w,GridUnitType.Star)});grid.Children.Add(library);Grid.SetColumn(results,2);grid.Children.Add(results);var host=new DockPanel();Grid.SetColumn(host,4);grid.Children.Add(host);DockPanel.SetDock(viewerBar,Dock.Top);host.Children.Add(viewerBar);var listHost=new DockPanel();DockPanel.SetDock(viewerCaption,Dock.Top);listHost.Children.Add(viewerCaption);listHost.Children.Add(viewerResults);viewerResultsPanel.Child=listHost;DockPanel.SetDock(viewerResultsPanel,Dock.Top);host.Children.Add(viewerResultsPanel);host.Children.Add(viewer);viewerBar.Children.Add(new TextBlock{Text="بحث داخل الملف:",Margin=new Thickness(4)});viewerBar.Children.Add(inside);LocalButton(viewerBar,"بحث داخلي",()=>Search(true));LocalButton(viewerBar,"نتائج الملف",()=>{ShowFileResults();return Task.CompletedTask;});LocalButton(viewerBar,"مزامنة",()=>{Sync();return Task.CompletedTask;});LocalButton(viewerBar,"السابق",()=>Navigate(-1));LocalButton(viewerBar,"التالي",()=>Navigate(1));LocalButton(viewerBar,"نسخ الفقرة",()=>{if(viewer.SelectedItem is DisplayRow row)Clipboard.SetText(row.Text);return Task.CompletedTask;});InitOutline(host);
