 public void VerifyViewerControls(){if(tools.Children.OfType<Button>().Any(b=>b.Content?.ToString() is "النتائج" or "نتائج الملف")||viewerBar.Children.OfType<Button>().Count(b=>b.Content?.ToString()=="نتائج الملف")!=1||viewerResultsPanel.Child==null||VirtualizingPanel.GetScrollUnit(viewer)!=ScrollUnit.Pixel||!viewerBar.Children.OfType<Button>().Any(b=>b.Content?.ToString()=="المخطط التفصيلي"))throw new InvalidOperationException("Viewer controls regression");}
 void WireResults(FastList list,bool tree){list.PreviewMouseLeftButtonUp+=async(_,e)=>{var row=FindRow(e.OriginalSource as DependencyObject);if(row==null)return;e.Handled=true;list.SelectedItem=row;await Activate(row,tree);};list.KeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter&&list.SelectedItem is DisplayRow row){e.Handled=true;await Activate(row,tree);}};}
 async Task Activate(DisplayRow row,bool tree){if(row.Hit!=null&&row.Context!=null)await Show(row.Hit,row.Context);else if(tree){row.Open=!row.Open;RefreshResults();}}
 static DisplayRow? FindRow(DependencyObject? d){while(d!=null){if(d is FrameworkElement f&&f.DataContext is DisplayRow r)return r;d=d is FrameworkContentElement c?c.Parent:VisualTreeHelper.GetParent(d);}return null;}
 static bool Contains(DisplayRow parent,DisplayRow target)=>ReferenceEquals(parent,target)||parent.Children.Any(c=>Contains(c,target));
 Button Add(string label,Func<Task> action,bool busy=true){var b=LocalButton(tools,label,action);if(busy)busyButtons.Add(b);return b;}
 Button LocalButton(Panel panel,string label,Func<Task> action){var b=new Button{Content=label,Margin=new Thickness(3),Padding=new Thickness(6)};panel.Children.Add(b);b.Click+=async(_,_)=>{try{await action();}catch(Exception e){errors.Add(e.ToString());status.Text=e.Message;}};return b;}
 async Task Work(Func<CancellationToken,Task> action){if(cancel!=null){status.Text="انتظر اكتمال العملية أو ألغها أولًا";return;}using var c=new CancellationTokenSource();cancel=c;foreach(var b in busyButtons)b.IsEnabled=false;try{await action(c.Token);}catch(OperationCanceledException){status.Text="تم الإلغاء";}catch(Exception e){errors.Add(e.ToString());status.Text=e.Message;}finally{cancel=null;foreach(var b in busyButtons)b.IsEnabled=true;}}
 async Task Folder(){var d=new OpenFolderDialog{Title="اختر مجلد ملفات DOCX"};if(d.ShowDialog(this)!=true)return;await Work(async t=>{var scan=await Task.Run(()=>Core.Scan(d.FolderName,t),t);errors.AddRange(scan.Errors);Merge(scan.Files);});}
 void Merge(IEnumerable<string> paths){foreach(var p in paths)if(!files.Contains(p,StringComparer.OrdinalIgnoreCase)){files.Add(p);selected.Add(p);}Directory.CreateDirectory(Path.GetDirectoryName(settings)!);File.WriteAllText(settings,JsonSerializer.Serialize(files));Rebuild();}
 void Rebuild(){library.Items.Clear();foreach(var g in files.OrderBy(p=>p).GroupBy(p=>Path.GetDirectoryName(p)??"")){var folder=new TreeViewItem{Header=g.Key,Background=Brushes.Honeydew,IsExpanded=true};library.Items.Add(folder);foreach(var p in g){var box=new CheckBox{Content=Path.GetFileName(p),ToolTip=p,Background=Brushes.LightBlue,IsChecked=selected.Contains(p),Margin=new Thickness(4)};box.Checked+=(_,_)=>selected.Add(p);box.Unchecked+=(_,_)=>selected.Remove(p);folder.Items.Add(box);}}}
 async Task Search(bool local){var words=Core.Terms(local?inside.Text:query.Text);if(words.Length==0){status.Text="اكتب كلمات البحث";return;}if(local&&current==null){status.Text="افتح ملفًا من نتائج البحث أولًا";return;}var scope=local?new[]{current!.Path}:(selected.Count==0?files:files.Where(selected.Contains)).ToArray();if(scope.Length==0){status.Text="أضف ملفات أولًا";return;}await Work(async token=>{var watch=Stopwatch.StartNew();status.Text="جار البحث المباشر وجمع النتائج…";var scan=await Task.Run(()=>{var hits=new List<SearchHit>();var failures=new List<string>();foreach(var path in scope){token.ThrowIfCancellationRequested();try{foreach(var h in cache.Search(path,words,token))hits.Add(new SearchHit{Path=h.Path,Index=h.Index,Text=h.Text,Words=words,Length=h.Length,Ticks=h.Ticks,Offset=words.Min(w=>h.Text.IndexOf(w,StringComparison.OrdinalIgnoreCase))});}catch(Exception e) when(e is not OperationCanceledException){failures.Add(path+": "+e.Message);}}return(hits,failures);},token);token.ThrowIfCancellationRequested();errors.AddRange(scan.failures);var group=new DisplayRow{Text=$"{(local?"داخل الملف":"بحث عام")}: {string.Join(" + ",words)} ({scan.hits.Count})",Depth=0,Fill=Brushes.Lavender,Contexts=new Dictionary<string,FileResultContext>(StringComparer.OrdinalIgnoreCase)};foreach(var folder in scan.hits.GroupBy(h=>Path.GetDirectoryName(h.Path)??"")){var f=new DisplayRow{Text=folder.Key,Depth=1,Fill=Brushes.Honeydew,Indent=new Thickness(12,2,0,2)};group.Children.Add(f);foreach(var file in folder.GroupBy(h=>h.Path)){var n=new DisplayRow{Text=$"{Path.GetFileName(file.Key)} ({file.Count()})",Depth=2,Fill=Brushes.LightBlue,Indent=new Thickness(24,2,0,2)};f.Children.Add(n);var context=new FileResultContext(group,file.Key,words,file.ToArray());group.Contexts.Add(file.Key,context);n.Children.AddRange(context.Rows);}}if(!local){groups.Clear();groups.Add(group);phase=0;fold.Content="طي نتائج المكتبة";RefreshResults();}else if(current!=null&&current.Path.Equals(scope[0],StringComparison.OrdinalIgnoreCase)){if(!group.Contexts.TryGetValue(scope[0],out var context))context=new FileResultContext(group,scope[0],words,Array.Empty<SearchHit>());if(context.Rows.Count>0)await Show(context.Rows[0].Hit!,context);else SetContext(context);ShowFileResults();}watch.Stop();status.Text=$"{scan.hits.Count} نتيجة — بحث وتجهيز: {watch.ElapsedMilliseconds} ms — أخطاء: {scan.failures.Count}";});}
 void RefreshResults(){var visible=new List<DisplayRow>();void AddRows(DisplayRow r){visible.Add(r);if(r.Open)foreach(var c in r.Children)AddRows(c);}foreach(var g in groups)AddRows(g);results.ItemsSource=visible;}
 void SetContext(FileResultContext context){activeContext=context;if(ReferenceEquals(boundContext,context))return;boundContext=context;viewerResults.ItemsSource=context.Rows;viewerCaption.Text=$"{Path.GetFileName(context.Path)} — {string.Join(" + ",context.Words)} — {context.Rows.Count} نتيجة";}
 void ShowFileResults(){if(current==null||activeContext==null){status.Text="افتح نتيجة من البحث العام أولًا";return;}SetContext(activeContext);viewerResultsPanel.Visibility=Visibility.Visible;}
 IEnumerable<DisplayRow> AllRows(DisplayRow r){yield return r;foreach(var c in r.Children)foreach(var n in AllRows(c))yield return n;}
 void Fold(){if(groups.Count==0)return;phase=(phase+1)%4;foreach(var r in groups.SelectMany(AllRows)){if(r.Depth==0)r.Open=true;if(r.Depth==1)r.Open=phase!=2;if(r.Depth==2)r.Open=phase==0;}fold.Content=new[]{"طي نتائج المكتبة","طي ملفات النتائج","فرد ملفات النتائج","فرد نتائج المكتبة"}[phase];RefreshResults();}
 DisplayRow ParagraphRow(string text,int index,SearchHit hit)=>new(){Text=text,Words=hit.Words,Jump=index==hit.Index,Fill=index==hit.Index?Brushes.LightCyan:Brushes.White};
 async Task Show(SearchHit hit,FileResultContext context){int request=++version;var watch=Stopwatch.StartNew();try{var doc=await Task.Run(()=>cache.Get(hit.Path));if(request!=version)return;if(doc.Length!=hit.Length||doc.Ticks!=hit.Ticks||hit.Index>=doc.Paragraphs.Length||doc.Paragraphs[hit.Index]!=hit.Text)throw new IOException("تغيّر الملف؛ أعد البحث لتحديث النتائج");if(!ReferenceEquals(displayed,doc)||!displayedWords.SequenceEqual(hit.Words)){paragraphs=new ObservableCollection<DisplayRow>(doc.Paragraphs.Select((text,index)=>ParagraphRow(text,index,hit)));viewer.ItemsSource=paragraphs;displayed=doc;displayedWords=hit.Words;}else{if(current!=null&&current.Index<paragraphs.Count)paragraphs[current.Index]=ParagraphRow(doc.Paragraphs[current.Index],current.Index,hit);paragraphs[hit.Index]=ParagraphRow(doc.Paragraphs[hit.Index],hit.Index,hit);}current=hit;SetContext(context);OutlineDocumentChanged(doc);viewer.SelectedIndex=hit.Index;viewer.ScrollIntoView(paragraphs[hit.Index]);await Dispatcher.InvokeAsync(()=>{if(request==version){viewer.UpdateLayout();if(viewer.ItemContainerGenerator.ContainerFromIndex(hit.Index) is DependencyObject c)FindBlock(c)?.JumpNow();}},DispatcherPriority.Loaded);if(request==version)status.Text=$"{Path.GetFileName(hit.Path)} — فقرة {hit.Index+1} — فتح: {watch.ElapsedMilliseconds} ms";}catch(Exception e){if(request==version){errors.Add(e.ToString());status.Text=e.Message;}}}
 static HighlightBlock? FindBlock(DependencyObject d){if(d is HighlightBlock b)return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++){var found=FindBlock(VisualTreeHelper.GetChild(d,i));if(found!=null)return found;}return null;}
 void Sync(){if(current==null||activeContext==null){status.Text="افتح نتيجة أولًا";return;}ShowFileResults();var target=activeContext.Find(current.Index);if(target==null){status.Text="الفقرة المفتوحة ليست من نتائج البحث الحالي";return;}viewerResults.SelectedItem=target;viewerResults.ScrollIntoView(target);var root=activeContext.Root;if(groups.Contains(root)){foreach(var r in AllRows(root))if(Contains(r,target))r.Open=true;RefreshResults();results.SelectedItem=target;results.ScrollIntoView(target);}}
 async Task Navigate(int direction){if(current==null||activeContext==null)return;var context=activeContext;var hit=context.Next(current.Index,direction);if(hit==null)hit=(direction>0?context.Rows.FirstOrDefault(r=>r.Hit!.Index>current.Index):context.Rows.LastOrDefault(r=>r.Hit!.Index<current.Index))?.Hit;if(hit==null){status.Text="لا توجد نتيجة أخرى في الملف بهذا الاتجاه";return;}await Show(hit,context);}
